covered_bond_dual_recourse<-function(cover_pool,cover_pool_paths,bond_contract,issuer_paths,context=NULL){
 pool<-.cr_sc_checked(cover_pool,'CreditAssetPool');paths<-.cr_sc_checked(cover_pool_paths,'AssetPoolPaths');if(!(pool$profile$product_kind%in%c('MORTGAGE_COVER','PUBLIC_SECTOR_COVER'))||paths$pool_hash!=pool$sha256) .cr_error('STRUCTURED_ROUTE','Matched mortgage/public-sector cover pool required');b<-bond_contract;.cr_data_required(b,c('bond_id','version','currency','legal_profile_id','principal','original_maturity','interest_schedule','extension_interest_schedule','extension_rule','cover_cash_convention','estate_rule','innovation_hash'));.cr_sc_nullable(b,'extended_maturity');for(k in c('bond_id','version','currency','legal_profile_id')) .cr_sc_text(b[[k]],k);principal<-.cr_sc_number(b$principal,'principal',0);if(principal==0) .cr_error('STRUCTURED_COVERED','Positive principal required');origin<-paths$origin;maturity<-b$original_maturity;extended<-b$extended_maturity
 if(.cr_data_date(maturity,'original_maturity')<=.cr_data_date(origin,'origin')||(!is.null(extended)&&.cr_data_date(extended,'extended_maturity')<=.cr_data_date(maturity,'original_maturity'))) .cr_error('STRUCTURED_CALENDAR','Original maturity after origin and extension strictly later required');if(!(b$extension_rule%in%c('NONE','ISSUER_DEFAULT_AND_DECLARED_TRIGGER'))||(b$extension_rule=='NONE'&&!is.null(extended))||(b$extension_rule!='NONE'&&is.null(extended))||b$cover_cash_convention!='SEGREGATED_UNTIL_ISSUER_DEFAULT'||b$estate_rule!='RESIDUAL_AFTER_COMPLETE_COVER') .cr_error('STRUCTURED_COVERED','Explicit extension, segregation and residual-estate conventions required');if(b$innovation_hash!=paths$innovation_hash||b$currency!=pool$profile$currency) .cr_error('STRUCTURED_SHARED_PATHS','Issuer and cover scenarios must share innovation binding and currency')
 for(key in c('interest_schedule','extension_interest_schedule')){if(!is.list(b[[key]])||(length(b[[key]])&&is.null(names(b[[key]])))) .cr_error('STRUCTURED_COVERED','Interest schedules must be dated mappings');for(date in names(b[[key]])){.cr_sc_number(b[[key]][[date]],'interest_due',0);.cr_data_date(date,'interest_date');if((key=='interest_schedule'&&!(origin<date&&date<=maturity))||(key=='extension_interest_schedule'&&(is.null(extended)||!(maturity<date&&date<=extended)))) .cr_error('STRUCTURED_CALENDAR','Coupon dates must fit original or extension term')}}
 rows<-.cr_data_rows(issuer_paths,'issuer_paths');imap<-list();last_claim_date<-if(is.null(extended))maturity else extended
 for(row in rows){.cr_data_required(row,c('scenario_id','issuer_capacity','extension_triggered','estate_payment_date','estate_recovery_fraction','estate_capacity'));.cr_sc_nullable(row,'issuer_default_date');sid<-row$scenario_id;if(!(sid%in%unlist(paths$scenario_ids,use.names=FALSE))||!is.null(imap[[sid]])) .cr_error('STRUCTURED_COVERED','Unique aligned issuer scenario rows required');default<-row$issuer_default_date;settlement<-row$estate_payment_date;if(!is.null(default)&&.cr_data_date(default,'issuer_default_date')<.cr_data_date(origin,'origin')) .cr_error('STRUCTURED_CALENDAR','Issuer default may start at origin, not before');if(.cr_data_date(settlement,'estate_payment_date')<max(.cr_data_date(tail(paths$dates,1)[[1]],'pool_end'),.cr_data_date(last_claim_date,'last_claim_date'))) .cr_error('STRUCTURED_CALENDAR','Residual estate settlement must follow full cover calendar and possible maturity');if(!is.null(default)&&default>settlement) .cr_error('STRUCTURED_CALENDAR','Default after settlement is outside scenario horizon');if(!is.logical(row$extension_triggered)||length(row$extension_triggered)!=1L||is.na(row$extension_triggered)||(row$extension_triggered&&(b$extension_rule=='NONE'||is.null(default)||default>maturity))) .cr_error('STRUCTURED_EXTENSION','Extension requires declared rule and issuer default by original maturity');.cr_sc_number(row$estate_recovery_fraction,'estate_recovery_fraction',0,1);.cr_sc_number(row$estate_capacity,'estate_capacity',0);if(!is.list(row$issuer_capacity)||(length(row$issuer_capacity)&&is.null(names(row$issuer_capacity)))) .cr_error('STRUCTURED_COVERED','Dated issuer cash capacity mapping required');for(date in names(row$issuer_capacity)){.cr_sc_number(row$issuer_capacity[[date]],'issuer_capacity',0);if(!(.cr_data_date(origin,'origin')<=.cr_data_date(date,'capacity_date')&&.cr_data_date(date,'capacity_date')<=.cr_data_date(settlement,'estate_payment_date'))) .cr_error('STRUCTURED_CALENDAR','Issuer capacity outside scenario horizon')};imap[[sid]]<-row}
 if(!setequal(names(imap),unlist(paths$scenario_ids,use.names=FALSE))) .cr_error('STRUCTURED_COVERED','Full aligned issuer scenarios required');if(any(vapply(paths$ending_states,function(e)!e$terminal_complete,TRUE))) .cr_error('STRUCTURED_UNRESOLVED','Residual estate calculation requires complete cover runoff');ctx<-.cr_result(NULL,'structured.context',context=context)$context;if((!is.null(ctx$currency)&&ctx$currency!=b$currency)||(!is.null(ctx$probability_measure)&&ctx$probability_measure!='PHYSICAL')||(!is.null(ctx$conditioning)&&ctx$conditioning!=paths$scenario_contract$conditioning)) .cr_error('TARGET_MISMATCH','Covered bond result context conflicts with physical paths');horizon_end<-max(vapply(rows,function(r)r$estate_payment_date,''));if((!is.null(ctx$time_unit)&&ctx$time_unit!='days')||(!is.null(ctx$horizon)&&ctx$horizon!=as.numeric(.cr_data_date(horizon_end,'horizon_end')-.cr_data_date(origin,'origin')))) .cr_error('TARGET_MISMATCH','Covered bond context must match actual final settlement-day horizon');ledgers<-ends<-list();keyfn<-function(s,d).cr_hash(list(s,d));cash<-setNames(paths$cashflows,vapply(paths$cashflows,function(r)keyfn(r$scenario_id,r$date),''))
 for(sid in paths$scenario_ids){
 row<-imap[[sid]];default<-row$issuer_default_date;extension<-row$extension_triggered;due_date<-if(extension)extended else maturity;interest<-b$interest_schedule;if(extension)for(d in names(b$extension_interest_schedule))interest[[d]]<-.cr_sc_sum(c(if(is.null(interest[[d]]))0 else interest[[d]],b$extension_interest_schedule[[d]]));calendar<-sort(unique(c(unlist(paths$dates,use.names=FALSE),names(interest),names(row$issuer_capacity),maturity,due_date,row$estate_payment_date,default)));outstanding_principal<-outstanding_interest<-cover_balance<-issuer_total<-cover_total<-estate_total<-original_shortfall<-effective_maturity_shortfall<-0;late_interest<-FALSE
 for(date in calendar){
 principal_due<-if(date==due_date)principal else 0;coupon_due<-if(is.null(interest[[date]]))0 else interest[[date]];outstanding_principal<-.cr_sc_sum(c(outstanding_principal,principal_due));outstanding_interest<-.cr_sc_sum(c(outstanding_interest,coupon_due));pc<-cash[[keyfn(sid,date)]];net_cover<-if(is.null(pc))0 else .cr_sc_sum(c(pc$principal_available,pc$interest_available,pc$recovery_gross,-pc$workout_cost,-pc$servicing_cost));opening_cover<-cover_balance;cover_balance<-.cr_sc_sum(c(cover_balance,net_cover));claim<-.cr_sc_sum(c(outstanding_principal,outstanding_interest));in_default<-!is.null(default)&&date>=default;capacity<-if(is.null(row$issuer_capacity[[date]]))0 else row$issuer_capacity[[date]];issuer_payment<-if(!in_default)min(claim,capacity)else 0;claim<-claim-issuer_payment;cover_payment<-if(in_default)min(claim,max(0,cover_balance))else 0;cover_balance<-cover_balance-cover_payment;claim<-claim-cover_payment;estate_payment<-if(in_default&&date==row$estate_payment_date)min(claim*row$estate_recovery_fraction,row$estate_capacity)else 0;paid<-.cr_sc_sum(c(issuer_payment,cover_payment,estate_payment));interest_paid<-min(outstanding_interest,paid);outstanding_interest<-max(0,outstanding_interest-interest_paid);principal_paid<-min(outstanding_principal,max(0,paid-interest_paid));outstanding_principal<-max(0,outstanding_principal-principal_paid);issuer_total<-.cr_sc_sum(c(issuer_total,issuer_payment));cover_total<-.cr_sc_sum(c(cover_total,cover_payment));estate_total<-.cr_sc_sum(c(estate_total,estate_payment));late_interest<-late_interest||outstanding_interest>1e-12*max(1,principal);if(date==maturity)original_shortfall<-if(extension)principal else outstanding_principal;if(date==due_date)effective_maturity_shortfall<-outstanding_principal;residual<-.cr_sc_sum(c(opening_cover,net_cover,-cover_payment,-cover_balance));ledgers[[length(ledgers)+1L]]<-list(scenario_id=sid,date=date,issuer_in_default=in_default,principal_due=principal_due,interest_due=coupon_due,issuer_payment=issuer_payment,cover_payment=cover_payment,estate_payment=estate_payment,interest_paid=interest_paid,principal_paid=principal_paid,outstanding_interest=outstanding_interest,outstanding_principal=outstanding_principal,cover_net_collection=net_cover,closing_cover_balance=cover_balance,cover_conservation_residual=residual)
 }
 total_claim<-.cr_sc_sum(c(principal,unlist(interest,use.names=FALSE)));total_payment<-.cr_sc_sum(c(issuer_total,cover_total,estate_total));shortfall<-.cr_sc_sum(c(outstanding_principal,outstanding_interest));if(abs(.cr_sc_sum(c(total_claim,-total_payment,-shortfall)))>1e-10*max(1,total_claim)) .cr_error('STRUCTURED_CONSERVATION','Dual recourse claim reconciliation failed');ends[[length(ends)+1L]]<-list(scenario_id=sid,extension_activated=extension,effective_maturity=due_date,contractual_claim=total_claim,issuer_payment=issuer_total,cover_payment=cover_total,estate_payment=estate_total,ultimate_shortfall=shortfall,ultimate_principal_shortfall=outstanding_principal,ultimate_interest_shortfall=outstanding_interest,original_date_principal_deferral_or_shortfall=original_shortfall,effective_maturity_principal_shortfall=effective_maturity_shortfall,timely_interest_failure=late_interest,unused_cover_cash=max(0,cover_balance),unfunded_cover_cost=max(0,-cover_balance))
 }
 value<-.cr_sc_bound(list(schema_version='1.0',kind='CoveredBondRecoursePaths',origin=origin,horizon_end=horizon_end,pool_hash=pool$sha256,pool_paths_hash=paths$sha256,bond_contract=b,issuer_paths_hash=.cr_hash(rows),innovation_hash=paths$innovation_hash,scenario_ids=paths$scenario_ids,scenario_weights=paths$scenario_weights,cashflows=ledgers,ending_states=ends));.cr_result(value,'structured_credit.covered_bond_dual_recourse','covered_bond_recourse',ctx,diagnostics=.cr_empty_object(),limitations='National insolvency priority, enforceability and maturity extension are externally supplied legal assumptions. Cover collections are segregated until issuer default; pre-default cash is not distributed to issuer. Normal issuer capacity pays due claims before default; thereafter cover pays and residual estate recovery is capped by remaining contractual claim and estate capacity. Estate settlement follows complete cover runoff and all possible maturity dates, avoiding competing future cover/estate recovery. Interest is paid before principal. Extension moves principal only and activates explicitly supplied extra coupons; original-date deferral is reported separately from effective-maturity failure. No penalty interest, issuer recovery uplift or double recovery is inferred.')
}
